// Filter out merchants already on Paytm, then score the rest.
// Same deterministic formula as app/agents/scoring.py — every point on a lead
// score maps to a named factor so it can be explained in the UI.
const body = $('Discovery Webhook').first().json.body || {};
const location = String(body.location || '');
const merchants = ($json.merchants || []);

const CATEGORY_FIT = { Cafe: 20, Restaurant: 20, Grocery: 18, Electronics: 18, Bakery: 16, Pharmacy: 16, 'Sweet Shop': 16, Fitness: 14, Apparel: 14, Salon: 12, Hardware: 10, Bookstore: 10, Stationery: 8 };
const VOLUME_BENCHMARK = 900000;
const inr = (v) => '₹' + Math.round(v).toLocaleString('en-IN');

const skipped = merchants.filter((m) => m.paytm_status === 'active');
const candidates = merchants.filter((m) => m.paytm_status !== 'active');

const prospects = candidates.map((m) => {
  const breakdown = [];
  const reasons = [];

  const volumePoints = Math.min(35, Math.round((m.estimated_volume || 0) / VOLUME_BENCHMARK * 35));
  breakdown.push({ factor: 'Transaction potential', points: volumePoints, max: 35, detail: inr(m.estimated_volume || 0) + ' estimated monthly volume (demo dataset)' });
  if (volumePoints >= 24) reasons.push('High estimated transaction potential (' + inr(m.estimated_volume) + '/month)');
  else if (volumePoints >= 14) reasons.push('Moderate transaction potential (' + inr(m.estimated_volume) + '/month)');
  else reasons.push('Low estimated volume (' + inr(m.estimated_volume) + '/month)');

  const categoryPoints = CATEGORY_FIT[m.category] ?? 10;
  breakdown.push({ factor: 'Category fit', points: categoryPoints, max: 20, detail: (m.category || 'Unclassified') + ' — digital-payment affinity' });
  if (categoryPoints >= 16) reasons.push(m.category + ' is a high-fit category for digital payments');

  const hasWebsite = Boolean(m.website);
  const hasContact = Boolean(m.contact);
  const digitalPoints = (hasWebsite ? 12 : 0) + (hasContact ? 8 : 0);
  let digitalDetail = 'No website and no reachable contact';
  if (hasWebsite && hasContact) { digitalDetail = 'Website and direct contact available'; reasons.push('Strong digital presence and a reachable contact'); }
  else if (hasContact) { digitalDetail = 'Direct contact available, no website'; reasons.push('Reachable contact, limited digital presence'); }
  else if (hasWebsite) { digitalDetail = 'Website available, no direct contact'; }
  else { reasons.push('No reachable contact in the demo dataset'); }
  breakdown.push({ factor: 'Digital presence', points: digitalPoints, max: 20, detail: digitalDetail });

  const inTerritory = !location || String(m.location || '').toLowerCase().includes(location.toLowerCase());
  breakdown.push({ factor: 'Territory match', points: inTerritory ? 15 : 0, max: 15, detail: inTerritory ? m.location + ' matches the mission territory' : m.location + ' is outside the mission territory' });
  if (inTerritory && location) reasons.push('Located in the target territory (' + m.location + ')');

  breakdown.push({ factor: 'Availability', points: 10, max: 10, detail: 'Not onboarded in the demo dataset' });
  reasons.push('Not onboarded in the demo dataset');

  const score = breakdown.reduce((sum, f) => sum + f.points, 0);
  const opportunity = score >= 80 ? 'High' : score >= 65 ? 'Medium' : 'Low';

  return { merchant: m, score, breakdown, reasons, opportunity };
});

prospects.sort((a, b) => b.score - a.score);

return [{ json: { success: true, matched: merchants.length, skipped_onboarded: skipped, prospects } }];
